query:
SELECT job_id, customer_name, date, time_slot, assigned_to, location FROM schedule_jobs 
WHERE customer_name LIKE '%Adrian%' OR customer_name LIKE '%miller%'
ORDER BY created_at DESC LIMIT 5;

SELECT employee_id, full_name, location FROM employees 
WHERE location = 'crestview' AND full_name LIKE '%Elijah%';

